$source=dirname(__DIR__);$sandbox=sys_get_temp_dir().'/lifeos-plugin-'.bin2hex(random_bytes(8));mkdir($sandbox.'/app/Modules',0700,true);define('ROOT',$sandbox);define('DATA',$sandbox.'/data');mkdir(DATA,0700);
foreach(['Db','Migrator','Modules','Router','helpers','Backup']as $file)require $source.'/app/Core/'.$file.'.php';foreach(['PlatformService','PluginTrustService']as $file)require $source.'/app/Modules/Platform/src/'.$file.'.php';
$n=0;function plcheck(bool $ok,string $label):void{global $n;if(!$ok)throw new RuntimeException($label);$n++;}function plreject(callable $f):void{try{$f();}catch(InvalidArgumentException|PDOException){plcheck(true,'Unsafe installation rejected');return;}throw new RuntimeException('Expected failure');}
try{Db::init(DATA.'/lifeos.db');Db::exec('CREATE TABLE migrations(file TEXT PRIMARY KEY,checksum TEXT,applied_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE platform_publishers(public_key TEXT PRIMARY KEY,name TEXT);CREATE TABLE platform_plugins(name TEXT PRIMARY KEY,sha256 TEXT,publisher TEXT);CREATE TABLE platform_audit(id INTEGER PRIMARY KEY,action TEXT,detail TEXT,actor TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP)');
