$make=function(string $id,string $sql,array $compat=[])use($sandbox,$pair){$path=$sandbox.'/'.$id.'.zip';$z=new ZipArchive();$z->open($path,ZipArchive::CREATE);$z->addFromString('module.json',json_encode(['id'=>$id,'name'=>$id,'route'=>'/'.strtolower($id),'version'=>'1.0.0','compatibility'=>$compat?:['module_api'=>1,'lifeos_min'=>'1.9.0','lifeos_max_exclusive'=>'2.0.0','php_min'=>'8.3.0']]));$z->addFromString('routes.php','<?php return function(Router $r){$r->get("/fixture-live",fn()=>"Fixture is live");};');$z->addFromString('migrations/001_create.sql',$sql);$z->close();return [$path,base64_encode(sodium_crypto_sign_detached(file_get_contents($path),sodium_crypto_sign_secretkey($pair)))];};
[$path,$sig]=$make('FixturePlugin','CREATE TABLE fixture_data(id INTEGER PRIMARY KEY,title TEXT);');$preview=PluginTrustService::inspect($path,$pub,$sig);plcheck($preview['id']==='FixturePlugin','Compatibility and signature preview');PluginTrustService::install($path,$pub,$sig,$preview['sha256']);plcheck(is_file(ROOT.'/app/Modules/FixturePlugin/routes.php'),'Reviewed code activated');plcheck(Db::one("SELECT file FROM migrations WHERE file='FixturePlugin/001_create.sql'")!==null,'Migration tracked under permanent module identity');$mods=Modules::discover(ROOT.'/app/Modules');Migrator::run(array_map(fn($m)=>$m['path'].'/migrations',$mods));$router=new Router();Modules::register($mods,$router);ob_start();$router->dispatch('GET','/fixture-live');$html=ob_get_clean();plcheck($html==='Fixture is live','Installed plugin route actually executes');plreject(fn()=>PluginTrustService::install($path,$pub,$sig,$preview['sha256']));
