}finally{Db::close();$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($sandbox,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){if($f->isDir())rmdir($f->getPathname());else unlink($f->getPathname());}rmdir($sandbox);}echo "$n plugin lifecycle checks passed.\n";
